
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_task_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_task", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.881689146215207e+00, -4.782615610611435e+00, -4.643718062348062e+00, -4.451153769771275e+00, -4.188410031290668e+00, -3.837911992993869e+00, -3.384878906092868e+00, -2.824259140343472e+00, -2.172534038066509e+00, -1.467915794400732e+00, -6.845662227488546e-01, -5.174278502417664e-01, -6.317706140074931e-01, -5.276016177609276e-01, -3.571098538690756e-01, -1.883944830891064e-01, -6.669882445952857e-02, -2.261455904451469e-02, -3.712470070697039e-03, -1.778103091863968e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


